export function sampleT(locale, key, vars) {
  const table = sampleLocales[locale] || sampleLocales.en;
  let text = table[key] ?? sampleLocales.en[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
  }
  return text;
}

export const SAMPLE_LOCALE_KEYS = Object.keys(baseEn);
